drawTreasureCard:
drawTreasureCard: () => {
      const state = get().gameState;
      if (!state) return;

      const hero = state.heroes.find(h => h.id === state.currentHeroId);
      if (!hero) return;

      const result = TreasureSystem.drawTreasureCard(state, hero);
      if (result.card) {
        if (result.card.treasureType === 'blessing') {
          TreasureSystem.useBlessing(state, result.card, hero);
        } else if (result.card.treasureType === 'fortune') {
          TreasureSystem.useFortune(state, result.card, hero);
        } else {
          TreasureSystem.assignItem(state, result.card, hero);
        }

        // Populate log
        const logEntry: import('../../game/types').GameLogEntry = {
          id: Math.random().toString(),
          timestamp: new Date().toLocaleTimeString(),
          message: result.message,
          type: 'event'
        };

        const newLog = [...(state.log || []), logEntry];
        set({ gameState: { ...state, heroes: [...state.heroes], log: newLog } });
      }
    },

