startNewGame:
startNewGame: (scenarioId: string, heroIds: string[]) => {
      console.log('[DEBUG] gameStore.startNewGame: Called with scenarioId:', scenarioId, 'heroIds:', heroIds);
      const dataLoader = DataLoader.getInstance();
      const allScenarios = dataLoader.getScenarios();
      console.log('[DEBUG] gameStore.startNewGame: Available scenarios:', allScenarios.map(s => s.id));
      const scenario = dataLoader.getScenarios().find(s => s.id === scenarioId);
      console.log('[DEBUG] gameStore.startNewGame: Found scenario:', scenario);
      const allHeroes = dataLoader.getHeroes();
      console.log('[DEBUG] gameStore.startNewGame: Available heroes:', allHeroes.map(h => h.id));
      const selectedHeroes = heroIds.map(id => allHeroes.find(h => h.id === id)).filter(Boolean) as Hero[];
      console.log('[DEBUG] gameStore.startNewGame: Selected heroes:', selectedHeroes);

      if (!scenario) {
        console.error('[ERROR] gameStore.startNewGame: Scenario not found for ID:', scenarioId);
        return;
      }

      const initialState: GameState = {
        phase: 'setup',
        currentHeroId: selectedHeroes[0].id,
        heroes: selectedHeroes,
        monsters: [],
        tiles: (() => {
          const startTileTemplate = DataLoader.getInstance().getTileById(scenario.startTileId);
          if (!startTileTemplate) {
            console.error('[ERROR] Start tile template not found:', scenario.startTileId);
            return [];
          }
          return [{
            ...startTileTemplate,
            x: 0, z: 0,
            isRevealed: true,
            isStart: true,
            isExit: false,
            rotation: 0,
            monsters: [],
            heroes: selectedHeroes.map(h => h.id),
            items: []
          }];
        })(),
        dungeonDeck: (() => {
          const allTiles = DataLoader.getInstance().getTiles();
          const startTileId = scenario.startTileId;
          const otherTileIds = allTiles
            .filter(t => t.id !== startTileId)
            .map(t => t.id);

          // Fisher-Yates shuffle
          for (let i = otherTileIds.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [otherTileIds[i], otherTileIds[j]] = [otherTileIds[j], otherTileIds[i]];
          }
          return otherTileIds;
        })(),
        treasureDeck: (() => {
          const treasureTypes = ['treasure', 'item', 'consumable', 'weapon', 'summon'];
          const treasureIds = DataLoader.getInstance()
            .getAllCards()
            .filter(c => treasureTypes.includes(c.type))
            .map(c => c.id);

          console.log(`[gameStore] Initialized treasure deck with ${treasureIds.length} cards.`);

          // Inline Fisher-Yates shuffle
          for (let i = treasureIds.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [treasureIds[i], treasureIds[j]] = [treasureIds[j], treasureIds[i]];
          }
          return treasureIds;
        })(),
        encounterDeck: (() => {
          const encounterIds = DataLoader.getInstance()
            .getAllCards()
            .filter(c => c.type === 'encounter')
            .map(c => c.id);

          // Inline Fisher-Yates shuffle
          for (let i = encounterIds.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [encounterIds[i], encounterIds[j]] = [encounterIds[j], encounterIds[i]];
          }
          return encounterIds;
        })(),
        monsterDeck: (() => {
          const monsterIds = DataLoader.getInstance()
            .getMonsters()
            .map(m => m.id);

          // Inline Fisher-Yates shuffle
          for (let i = monsterIds.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [monsterIds[i], monsterIds[j]] = [monsterIds[j], monsterIds[i]];
          }
          return monsterIds;
        })(),
        discardPiles: {
          treasure: [],
          encounter: [],
          ability: [],
          monster: []
        },
        activeScenario: scenario,
        turnOrder: selectedHeroes.map(h => h.id),
        healingSurges: scenario.maxSurges,
        turnCount: 0,
        log: [{
          id: 'start',
          timestamp: new Date().toLocaleTimeString(),
          message: `Scenario started: ${scenario.name}`,
          type: 'system'
        }],
        // New state fields
        activeEnvironmentCard: null,
        experiencePile: [],
        treasuresDrawnThisTurn: 0,
        traps: [],
        villainPhaseQueue: [],
        activeVillainId: null,
        // Power Selection state
        // Persisted automatically via SaveSystem — no extra work needed.
        powerSelections: selectedHeroes.map(hero => ({
          heroId: hero.id,
          selectedPowerIds: [],
          isConfirmed: false
        })),
        activeConditions: [],
        cardResolution: {
          phase: 'idle',
          cardId: null,
          cardType: null,
          pendingEffects: [],
          resolvedEffects: [],
          targetEntityId: null,
          result: null,
        }
      };

      set({ gameState: initialState });
    },

